"use client";
/* Duck, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Duck(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("duck"); }, []);
  return React.createElement("piix-pal", { "pal": "duck", ...piixAttrs(props) });
}

export default Duck;
